// ---------------------------------------------------------------------------
template<class Traverser, class Func>
inline void omp_trav_for_each(const Traverser &trav, const Func &func) {
	#pragma omp parallel for schedule(static)
	for (auto inner_trav : trav) {
		inner_trav.for_each(func);
	}
