	using namespace noarr;

	const auto n = A | get_length<'i'>();
	const num_t n_as_num = static_cast<num_t>(n);

	// Simple 1D traversal; cost is negligible compared to the kernel,
	// so we keep it serial and straightforward.
	traverser(A, B).for_each([&](auto state) {
		const auto i = get_index<'i'>(state);

		A[state] = (static_cast<num_t>(i) + static_cast<num_t>(2)) / n_as_num;
		B[state] = (static_cast<num_t>(i) + static_cast<num_t>(3)) / n_as_num;
	});
