	auto blocked_interior =
		interior
		^ noarr::into_blocks_dynamic<'i', 'I', 'i', 'r'>(block_size_lit)
		^ noarr::hoist<'I'>();

	constexpr num_t one_third = static_cast<num_t>(0.33333);

