// computation kernel
//
// Optimizations:
//  - Fuse the two spatial sweeps (A -> B and B -> A) into a single traversal
//    per time step. This improves data locality by:
//      * reusing freshly computed B values from registers when updating A
//      * avoiding an extra full pass over B for the second sweep
//  - Use a simple 3-point sliding window over B (b_im2, b_im1, new_b) to
//    implement the second sweep while iterating i only once.
//  - Keep the PolyBench SCoP region (#pragma scop / endscop) and Noarr-based
//    traversal structure intact.
[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	auto n = A | get_length<'i'>();

	// nothing to do if there are no interior points or no time steps
	if (n <= 2 || tsteps <= 0)
		return;

	// structure used only to iterate over time steps
	auto time_struct = noarr::scalar<num_t>() ^ noarr::vector<'t'>(static_cast<std::size_t>(tsteps));

	// view selecting interior points i in [1, n-2]
	auto interior = noarr::slice<'i'>(1, n - 2);

	// constant used in all stencil updates
	const num_t c = static_cast<num_t>(0.33333);

	#pragma scop
	traverser(time_struct).for_each([=](auto /*t_state*/) {
		// For each time step we conceptually perform:
		//   1) B[i] = c * (A[i-1] + A[i] + A[i+1])
		//   2) A[i] = c * (B[i-1] + B[i] + B[i+1])
		// for i in [1, n-2].
		//
		// Here we fuse these two sweeps into a single traversal over i by
		// maintaining a sliding window of three B values:
		//   b_im2 = B[i-2], b_im1 = B[i-1], new_b = B[i]
		// and updating A[i-1] once new_b is known. This keeps B[i-1] and
		// B[i-2] in registers and avoids reloading them from memory in a
		// separate second pass.

		// Left boundary value B[0] is not updated by the kernel and acts as
		// a fixed boundary during this time step.
		num_t b_im2 = B.template at<'i'>(0); // B[0]
		num_t b_im1 = num_t{};              // will be initialized at i == 1
		bool first = true;                  // marks the first interior point

		// First and second sweeps fused:
		//  - compute B[i] from A[*] (first sweep)
		//  - starting at i == 2, update A[i-1] from the sliding window over B (second sweep)
		traverser(B, A).order(interior).for_each([&](auto state) {
			// i index of the current interior point
			auto left_state  = state - noarr::idx<'i'>(1);
			auto right_state = state + noarr::idx<'i'>(1);

			// First sweep: update B[i] from A
			num_t new_b = c * (A[left_state] + A[state] + A[right_state]);
			B[state] = new_b;

			if (!first) {
				// For i >= 2 we have:
				//   b_im2 = B[i-2], b_im1 = B[i-1], new_b = B[i]
				// so we can now update A[i-1].
				auto prev_state = state - noarr::idx<'i'>(1); // index i-1
				A[prev_state] = c * (b_im2 + b_im1 + new_b);

				// Slide the window one step to the right:
				b_im2 = b_im1;
				b_im1 = new_b;
			} else {
				// i == 1: only initialize the window (B[0], B[1])
				b_im1 = new_b; // B[1]
				first = false;
			}
		});

		// After the fused loop, we have processed A[1..n-3].
		// The last interior point A[n-2] still needs to be updated:
		//   A[n-2] = c * (B[n-3] + B[n-2] + B[n-1])
		// At this point:
		//   b_im2 = B[n-3], b_im1 = B[n-2]
		// and B[n-1] is the fixed right boundary.
		auto last_inner = noarr::idx<'i'>(n - 2);
		num_t b_right_boundary = B.template at<'i'>(n - 1); // B[n-1]
		A[last_inner] = c * (b_im2 + b_im1 + b_right_boundary);
	});
	#pragma endscop
}

} // namespace

