template<class Traverser, class Func>
inline void parallel_for_each_1d(const Traverser &trav, const Func &f) {
#ifdef _OPENMP
	auto range = trav.range(); // range over the outermost dimension ('i' here)
	auto size  = static_cast<std::ptrdiff_t>(range.size());

	#pragma omp parallel for
	for (std::ptrdiff_t idx = 0; idx < size; ++idx) {
		auto inner_trav = range[idx];
		inner_trav.for_each(f);
	}
#else
	// No OpenMP: just execute serially.
	trav.for_each(f);
#endif
}

