[[gnu::flatten, gnu::noinline]]
void kernel_jacobi_1d(int tsteps, auto A, auto B) {
	using namespace noarr;

	// spatial problem size
	const auto n = A | get_length<'i'>();

	// 3-point stencil weight
	const num_t weight = static_cast<num_t>(0.33333);

	// state increment used to access i-1 and i+1
	const auto step_i = noarr::idx<'i'>(1);

	// view selecting interior points i in [1, n-2]
	const auto interior = noarr::slice<'i'>(1, n - 2);

	// Pre-build traversers for the two sweeps. They describe *what* needs to be
	// traversed; calling for_each() actually performs the iteration.
	auto trav_B_from_A = traverser(B, A).order(interior); // first sweep
	auto trav_A_from_B = traverser(A, B).order(interior); // second sweep

	#pragma scop
	// One parallel region for all time steps to avoid recreating threads.
	#pragma omp parallel
	{
		for (int t = 0; t < tsteps; ++t) {
			// -----------------------------------------------------------------
			// First sweep: update B from A
			// Each iteration of the OpenMP loop gets an inner traverser with
			// a fixed 'i'; calling for_each on it runs the lambda exactly once.
			// This preserves the original element-wise semantics while
			// distributing i-indices across threads.
			// -----------------------------------------------------------------
			#pragma omp for schedule(static)
			for (auto trav_i : trav_B_from_A) {
				trav_i.for_each([&](auto state) {
					const auto left  = state - step_i;
					const auto right = state + step_i;

					B[state] = weight * (A[left] + A[state] + A[right]);
				});
			}

			// Implicit barrier here ensures all B[i] are up-to-date
			// before any thread proceeds to the second sweep.

			// -----------------------------------------------------------------
			// Second sweep: update A from B
			// Same parallelization strategy as above, but roles of A/B swapped.
			// -----------------------------------------------------------------
			#pragma omp for schedule(static)
			for (auto trav_i : trav_A_from_B) {
				trav_i.for_each([&](auto state) {
					const auto left  = state - step_i;
					const auto right = state + step_i;

					A[state] = weight * (B[left] + B[state] + B[right]);
				});
			}
			// Implicit barrier here ensures all A[i] for this time step are
			// written before we advance to the next time step.
		}
	}
	#pragma endscop
}

